Specification:
Two workers share a semaphore with one permit. A worker may acquire the permit more than once but must release it as many times before returning. Every interleaving must terminate and both workers must complete. On completion the program must print exactly one line `DONE done=1` and then exit; it must terminate.


Current program:
```rust
use std::sync::mpsc;
struct Sem {
    n: std::sync::Mutex<u32>,
    cv: std::sync::Condvar,
}
impl Sem {
    fn new(n: u32) -> Self {
        Self {
            n: std::sync::Mutex::new(n),
            cv: std::sync::Condvar::new(),
        }
    }
    fn acq(&self) {
        let mut c = self.n.lock().unwrap();
        while *c == 0 {
            c = self.cv.wait(c).unwrap();
        }
        *c -= 1;
    }
    fn rel(&self) {
        *self.n.lock().unwrap() += 1;
        self.cv.notify_one();
    }
}
fn main() {
    let (tx, rx) = mpsc::sync_channel::<u32>(0);
    let s = std::sync::Arc::new(Sem::new(1));
    let s1 = std::sync::Arc::clone(&s);
    let tx1 = tx.clone();
    let w1 = std::thread::spawn(move || {
        s1.acq();
        s1.acq();
        s1.rel();
        let _ = tx1;
        let _ = rx;
    });
    let s2 = std::sync::Arc::clone(&s);
    let w2 = std::thread::spawn(move || {
        s2.acq();
        s2.rel();
    });
    w1.join().unwrap();
    w2.join().unwrap();
    println!("DONE done=1");
}

```

Fix any concurrency defect and output the complete corrected Rust program, or if there is none reply exactly NO_ISSUES.

